// src/lib/k4FormGorselleri.ts
//
// K4 (ADR Paketleme Kontrol Formu) — orijinal docx'ten LibreOffice ile
// birebir (tasarım, tablo yapısı korunarak) PDF'e çevrilip 150 DPI PNG
// olarak dışa aktarılmış hâli — Belge Oluştur'daki K4 render edilirken
// arka plan görseli olarak kullanılır (K2/K3 ile aynı yöntem).
//
// NOT: Kullanıcının paylaştığı orijinal dosya, TEST/DEMO amaçlı DOLU bir
// kopyaydı (checkbox'ların çoğu işaretli, "Firma/Tesis: Elkon - 4 nolu
// Şube", "UN Numarası: UN 3077", "Sınıf: 9", "Tespit Edilen Uygunsuzluk:
// Herhangi Bir uygunsuzluk tespit edilmemiştir." gibi örnek veriler
// girilmişti). Belge Oluştur GENEL bir şablon üretim aracı olduğu ve
// K1/K2/K3 hep BOŞ form olarak geldiği için, bu görsel TUTARLILIK
// amacıyla BOŞALTILARAK üretildi:
//   - 69 checkbox content control'ün TÜMÜ (w14:checkbox/w14:checked +
//     SDT içindeki gerçek görünen "☒"/"☐" karakteri) işaretsize çevrildi
//     (python-docx'in yüksek seviye API'si bu content control'leri
//     görmediği için doğrudan XML/zip seviyesinde düzenlendi).
//   - Firma/Tesis, UN Numarası, Sınıf ve Tespit Edilen Uygunsuzluk
//     metin hücreleri boşaltıldı.
// Tasarım/yapı (başlık kutusu, tablo hücre birleşimleri) BİREBİR
// korunmuştur — yalnızca örnek veriler kaldırıldı.
//
// Bu dosya DİNAMİK import edilir (await import(...)) — ana sayfa yükünü
// artırmasın diye, yalnızca PDF üretilirken yüklenir.
//
// NOT: base64 verisi bilinçli olarak TEK SATIR (chunk'lanmamış) tutulur
// — çok sayıda "+" ile birleştirilmiş küçük parçalar, build sürecinde
// bir regex/AST işleminin aşırı yavaşlayıp bellek taşırmasına (OOM) yol
// açabiliyor.
//
// 2026-10-21: Görselin içindeki orijinal başlık tablosu (KONTROL FORMU / PAKETLEME KAPSAMINDA KONTROLLER /
// Doküman No / tarihler / Sayı No) kesilip çıkarıldı (dış çerçeve korunarak). "PAKETLEME KAPSAMINDA
// KONTROLLER" artık Belge Oluştur'un standart başlık kutusunda alt satır olarak basılıyor.

export const K4_FORM_SAYFA1 =
  "data:image/png;base64,";
